corrected_code:
const express = require('express');
const { Queue } = require('bullmq');

const app = express();
const complianceQueue = new Queue('compliance-exports', {
  connection: { host: process.env.REDIS_HOST, port: 6379 }
});

app.delete('/api/queues/compliance-exports/jobs/:jobId', async (req, res) => {
  if (!req.user || !req.user.organizationId) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  const { jobId } = req.params;

  const job = await complianceQueue.getJob(jobId);
  if (!job) {
    return res.status(404).json({ error: 'Compliance export job not found' });
  }

  // Validate job belongs to caller's organization
  if (job.data.organizationId !== req.user.organizationId) {
    return res.status(403).json({ error: 'Forbidden: cannot delete export job of another organization' });
  }

  await job.remove();
  res.json({ success: true, removedJobId: jobId });
});

app.listen(8008);
